"""Complete nonrecursive heapsort and its two callback interfaces."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='힙 정렬 · 콜백·정렬 계약·메모리 정렬',
                     sections=sections, questions=questions))


add('lib/sort.c', '배열 정렬 전체: 비재귀 힙과 원소 교환 전략',
    '최대 힙을 구성하고 큰 원소를 배열 뒤로 보내 오름차순 정렬합니다.',
    'sort_r는 바이트 오프셋으로 힙을 관리합니다. 잎까지 내려간 뒤 목표 원소의 위치를 역추적하는 bottom-up sift를 사용하며 추출 단계에서는 큰 원소 두 개를 처리합니다. sort는 문맥 없는 콜백을 wrapper로 연결합니다.',
    '유효한 배열 크기와 일관된 비교 함수를 제공해야 합니다. 기본 교환은 원소의 바이트를 옮기고,별도 참조나 보조 자료 갱신이 필요하면 사용자 교환 콜백을 사용할 수 있습니다.',
    [('파일 전체 구성', 'SPDX,비교 횟수와 설계 배경 주석,types/export/sort 헤더 다음 정렬 가능성 검사,32/64비트·바이트 교환,콜백 dispatch,부모 오프셋 계산,sort_r와 sort 및 각 export가 있습니다. 동적 할당·재귀·전역 가변 상태는 없습니다.'),
     ('기본 교환 선택', 'is_aligned는 원소 크기가4 또는8의 배수인지 확인합니다. 효율적인 비정렬 접근 설정이 없으면 base 주소의 하위 비트도 검사합니다.8바이트 가능하면64비트 교환,그 다음4바이트,그 외 바이트 교환을 선택합니다. CONFIG_64BIT가 없을 때64비트 교환 helper는 두 번의32비트 전송으로 구현됩니다.'),
     ('교환 helper와 표식', '세 helper는 뒤쪽부터 do-while로 교환하며0 크기를 직접 처리하는 일반 API가 아닙니다. SWAP_WORDS_64/32/BYTES/WRAPPER는 작은 정수를 함수 포인터 타입으로 표시한 내부 태그입니다. do_swap이 먼저 태그를 판별하므로 이 숫자를 실제 코드 주소로 호출하지 않습니다. 사용자 콜백에는 크기를 int로 변환해 전달하므로 크기 계약도 중요합니다.'),
     ('콜백 wrapper', 'wrapper는 일반 cmp와 swap을 보관합니다. do_cmp는 내부 NULL 태그이면 wrapper의 일반 comparator를 호출하고 그 외에는 priv를 전달합니다. do_swap도 wrapper와 일반 문맥 콜백을 구분합니다. sort가 만든 지역 wrapper는 동기 호출이 끝날 때까지 유효하며 비동기 저장 용도가 아닙니다.'),
     ('부모 오프셋과 초기 경계', '인덱스 j>0의 부모는(j-1)/2입니다. parent는 size&-size의 최하위 비트를 사용해 바이트 오프셋에서도 같은 부모 위치를 계산합니다. sort_r는 n=num*size,a=(num/2)*size를 준비하고 a==0이면 반환합니다. 정상적으로 표현 가능한 크기에서 num<2 또는 size==0을 처리하지만 이 조건이 곱셈 오버플로 검사인 것은 아닙니다.'),
     ('힙 구성과 두 원소 추출', 'a가 남아 있으면 힙 구성 위치를 앞으로 옮깁니다. 힙 구성 후 n>3*size이면 루트를 뒤로 보내고 두 자식 중 큰 쪽도 다음 뒤쪽 위치로 보냅니다. shift는 선택한 자식과 후속 처리 위치를 연결합니다. [a,n)은 자식보다 크거나 같은 힙 구간,[n,num*size)은 정렬 완료 구간이라는 불변식을 주석이 제시합니다.'),
     ('bottom-up sift와 마무리', '큰 자식을 따라 잎까지 내려가고,목표 원소와 비교하며 parent로 돌아와 삽입 위치를 찾습니다. 이후 경로를 따라 교환합니다. 마지막2개 또는3개 구간에서는 루트 교환과 필요 시 앞쪽 두 원소 비교로 끝냅니다. 이를 단순한 재귀 heapify 코드라고 설명하면 실제 비교 절약 방식을 놓칩니다.'),
     ('복잡도와 안정성', '평균·최악 비교 횟수는 O(n log n)이고 재귀 스택이나 크기 n의 임시 배열이 없어 알고리즘 보조 공간은 O(1)입니다. 비교·교환의 자체 비용은 별도입니다. 동등 키의 원래 순서를 유지하는 안정 정렬은 보장하지 않습니다. comparator에서 a-b를 무조건 반환하면 signed overflow로 순서가 깨질 수 있어 부호 비교 방식이 안전한 경우가 많습니다.'),
     ('실행 전제', '배열 저장소,원소 크기,포인터 산술,일관된 순서 관계는 호출자의 계약입니다. 함수가 입력 배열에 쓰므로 읽기 전용 메모리를 전달하면 안 됩니다. 이 파일은 동시 수정 잠금도 제공하지 않습니다. GNU void* 산술과 커널 컴파일 관례를 사용하므로 사용자 공간 검증은 의존성 대체와 컴파일 조건을 명시합니다.')],
    [('이 정렬이 입력 크기만큼 재귀 스택을 사용하는가?', '아니다. 비재귀 루프와 고정 개수 지역 변수를 사용한다', '그렇다. 각 원소마다 재귀 호출한다', '원문에 재귀 호출이나 동적 임시 배열이 없습니다. 힙 위치를 바이트 오프셋으로 추적합니다.'),
     ('같은 키의 입력 순서가 반드시 보존되는가?', '아니다. 안정 정렬을 보장하지 않는다', '그렇다. 모든 힙 정렬은 안정적이다', '멀리 떨어진 원소를 교환하며 동등 키의 원래 위치를 추적하는 장치가 없습니다.'),
     ('원소 크기가8의 배수이면 모든 환경에서64비트 교환을 선택하는가?', '아니다. 설정에 따라 base 주소 정렬도 확인한다', '그렇다. 주소 정렬은 절대 보지 않는다', 'CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS가 없으면 크기와 주소의 하위 비트를 함께 검사합니다.'),
     ('sort_r의 a==0 검사가 num*size의 모든 오버플로를 방지하는가?', '아니다. 사전 크기 유효성 검사가 필요하다', '그렇다. 크기 산술이 넘으면 항상 안전하게 복구한다', 'a와n은 이미 곱셈으로 계산됩니다. 정상 크기의 조기 반환 조건과 overflow 검증은 다릅니다.'),
     ('bottom-up sift가 먼저 하는 일은?', '큰 자식을 따라 잎까지 내려가 후보 경로를 찾는다', '배열 전체를 매번 다시 정렬한다', '잎에서 부모로 되돌아가 적절한 위치를 찾는 방식으로 비교 횟수를 줄입니다.')])

add('include/linux/sort.h', '정렬 헤더 전체: 문맥 있는 콜백과 일반 콜백',
    '두 정렬 API의 인자와 책임을 구분합니다.',
    'sort_r는 base,num,size,cmp_r_func_t,swap_r_func_t,priv를 받고 sort는 문맥 없는 cmp_func_t와 swap_func_t를 받습니다. 둘 다 void 반환으로 입력 배열을 제자리 변경합니다.',
    'swap_func는 NULL로 두어 구현의 기본 교환을 사용할 수 있습니다. comparator는 일관된 순서를 제공해야 하며 priv의 실제 해석은 콜백이 담당합니다.',
    [('전체 파일', 'SPDX,_LINUX_SORT_H guard,types.h include,두 함수 선언,#endif가 전부입니다. comparator typedef와 구체 힙 알고리즘은 이 파일에 정의되어 있지 않습니다.'),
     ('배열과 문맥', 'base는 변경 가능한 배열 시작 주소,num은원소 수,size는원소당 바이트 수입니다. sort_r의 const void* priv는 호출자가 제공하는 읽기 문맥을 comparator와 사용자 swap에 전달합니다. 타입이 지워진 포인터이므로 잘못된 실제 타입을 자동 검증하지 않습니다.'),
     ('반환과 소유권', 'void 반환은 새 배열을 돌려주지 않는다는 뜻입니다. 배열 메모리의 소유권을 가져가거나 자동 해제하지 않습니다. 객체 이동 때 다른 위치 정보를 고쳐야 하면 사용자 swap이 그 책임을 수행하도록 설계할 수 있습니다.'),
     ('선언과 구현 연결', 'sort와 sort_r의 콜백 타입은 서로 다릅니다. 구현의 wrapper가 일반 콜백을 연결하므로 무작정 함수 포인터 타입을 캐스팅해 전달할 이유가 아닙니다. 기본 swap 선택,작은 배열 처리,복잡도와 안정성은 구현에서 확인합니다.')],
    [('sort_r의 priv는 무엇인가?', '콜백에 전달할 호출자 문맥 포인터다', '정렬 결과 배열의 새 주소를 받는 출력 포인터다', 'base 배열을 제자리 정렬하며 priv는 cmp/swap의 추가 문맥입니다. 함수는void를 반환합니다.'),
     ('두 정렬 함수가 배열을 자동 해제하는가?', '아니다. 기존 배열을 변경할 뿐이다', '그렇다. 정렬 후 새 배열로 교체하고 원본을 해제한다', '인터페이스에는 새 배열 반환이 없고 구현도 동적 할당·해제를 하지 않습니다.'),
     ('사용자 swap 없이 사용할 수 있는가?', '있다. NULL이면 구현이 기본 교환을 선택한다', '없다. 반드시 별도 교환 함수를 작성해야 한다', '실제 구현은 원소 크기와 정렬 조건으로 기본 교환을 선택합니다. 특수 이동 처리가 필요할 때만 별도 swap을 사용합니다.')])
